_new_begin = r"""function clearBirthTimeError(role){const error=document.getElementById(role+'BirthTimeError');error.textContent='';error.classList.add('hidden')}
function failBirthTime(role,message,suffix){const error=document.getElementById(role+'BirthTimeError');error.textContent=message;error.classList.remove('hidden');document.getElementById(role+suffix).focus();throw new Error(message)}
function readBirthTime(role){const who=role==='a'?'your':"the other person's";const hourText=document.getElementById(role+'BirthHour').value.trim();const minuteText=document.getElementById(role+'BirthMinute').value.trim();if(!hourText&&!minuteText)return failBirthTime(role,'Enter '+who+' birth hour and minute, or mark the time unknown.','BirthHour');if(!/^\d{1,2}$/.test(hourText))return failBirthTime(role,'Enter '+who+' birth hour as a number from 00 to 23.','BirthHour');if(!/^\d{1,2}$/.test(minuteText))return failBirthTime(role,'Enter '+who+' birth minute as a number from 00 to 59.','BirthMinute');const hour=Number(hourText);const minute=Number(minuteText);if(hour>23)return failBirthTime(role,'Enter '+who+' birth hour from 00 to 23.','BirthHour');if(minute>59)return failBirthTime(role,'Enter '+who+' birth minute from 00 to 59.','BirthMinute');clearBirthTimeError(role);return String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0')+':00'}
function toggleUnknownTime(role){const unknown=document.getElementById(role+'UnknownTime').checked;document.getElementById(role+'BirthHour').disabled=unknown;document.getElementById(role+'BirthMinute').disabled=unknown;document.getElementById(role+'TimeSource').disabled=unknown;clearBirthTimeError(role)}
async function searchPlace(role){const q=document.getElementById(role+'PlaceQuery').value.trim();if(q.length<2)return alert('Enter a city/place to search.');const box=document.getElementById(role+'PlaceResults');box.textContent='Searching…';try{const r=await fetch('/api/study/places?q='+encodeURIComponent(q));const d=await r.json();if(!r.ok){box.textContent=d.detail||'Birthplace search failed.';return}placeCandidates[role]=d.candidates||[];if(!placeCandidates[role].length){box.textContent='No matches. Add region/country and try again.';return}box.innerHTML=placeCandidates[role].map((p,i)=>'<button type="button" onclick="choosePlace(\''+role+'\','+i+')">'+esc(p.display_name)+' · '+esc(p.iana_timezone)+'</button>').join('')}catch(e){box.textContent='Birthplace search failed.'}}
function choosePlace(role,index){const p=placeCandidates[role][index];selectedPlaces[role]=p;document.getElementById(role+'PlaceChosen').textContent='Selected: '+p.display_name+' · '+p.iana_timezone;document.getElementById(role+'PlaceResults').innerHTML=''}
function requireBirthField(role,suffix,message){const field=document.getElementById(role+suffix);field.focus();throw new Error(message)}
function birthPayload(role){const who=role==='a'?'your':"the other person's";const date=document.getElementById(role+'BirthDate').value;const unknown=document.getElementById(role+'UnknownTime').checked;const place=selectedPlaces[role];if(!date)requireBirthField(role,'BirthDate','Enter '+who+' birth date.');const time=unknown?null:readBirthTime(role);if(!place)requireBirthField(role,'PlaceQuery','Search and select '+who+' birthplace.');return {birth_date:date,local_time:time,birthplace:place.display_name,iana_timezone:place.iana_timezone,time_source:unknown?'unknown':document.getElementById(role+'TimeSource').value,uncertainty_minutes:null,latitude:place.latitude,longitude:place.longitude}}
async function beginStudy(){if(!llmConfigured)return alert('AI auditor is not ready.');const email=document.getElementById('contactEmail').value.trim();if(!email)return alert('Enter your email.');if(!document.getElementById('storageConsent').checked||!document.getElementById('partnerConsent').checked||!document.getElementById('llmConsent').checked)return alert('All three study consents are required.');let a,b;try{a=birthPayload('a');b=birthPayload('b')}catch(e){return alert(e.message)}const button=document.getElementById('beginButton');button.disabled=true;button.textContent='Sealing hidden prediction…';const status=document.getElementById('studyStatus');status.classList.remove('hidden');status.textContent='Calculating and freezing the pre-answer Astro/HD record. No relationship answer has been submitted yet.';try{const r=await fetch('/api/study/intake',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({intake:{contact_email:email,respondent_birth:a,partner_birth:b,consent_to_store_private_research_data:true,consent_to_process_partner_birth_data:true,created_at_utc:new Date().toISOString()},consent_to_llm_processing:true})});const d=await r.json();if(!r.ok){status.textContent=d.detail||'Could not save study intake.';button.disabled=false;button.textContent='Seal prediction & begin questionnaire';return}sessionId=d.session_id;token=d.resume_token;isStudySession=true;localStorage.setItem('rr_session',sessionId);localStorage.setItem('rr_token',token);if(!d.preflight.confirmatory_ready){status.textContent=d.participant_message+' Prediction status: '+JSON.stringify(d.preflight.prediction_layer_statuses);button.textContent='Prediction not ready';return}const state=await loadState();coreProgress(state.answers.length);if(state.next_question)showQuestion(state.next_question);else startAudit()}catch(e){status.textContent='Could not initialize the study.';button.disabled=false;button.textContent='Seal prediction & begin questionnaire'}}"""
