_new_freeze = r"""async function freezeCurrent(){const r=await fetch('/api/adaptive/sessions/'+sessionId+'/freeze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});const d=await r.json();if(!r.ok)return alert(d.detail||'Could not freeze');showDone(d.freeze_sha256,false,false);if(isStudySession)finishStudyAfterFreeze()}
async function finishStudyAfterFreeze(){document.getElementById('doneText').textContent='Your answers are sealed. Building the chart-blind relationship fingerprint…';const r=await fetch('/api/study/sessions/'+sessionId+'/phenotype-freeze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});const d=await r.json();if(!r.ok){document.getElementById('doneText').textContent=d.detail||'Phenotype classification failed; the answers remain safely frozen.';return}const f=await fetch('/api/study/sessions/'+sessionId+'/fingerprint?token='+encodeURIComponent(token));const fp=await f.json();if(!f.ok){document.getElementById('doneText').textContent=fp.detail||'Fingerprint is unavailable.';return}renderFingerprint(fp);document.getElementById('studyResults').classList.remove('hidden');document.getElementById('doneText').textContent='Your chart-blind relationship fingerprint is sealed. You can now reveal what the pre-answer Astro/HD system actually predicted.'}
function renderFingerprint(fp){const rows=(fp.classified_axes||[]).map(a=>'<div class="result-axis"><strong>'+esc(a.axis_id.replaceAll('_',' '))+'</strong> · '+esc(a.direction)+' · <strong>'+esc(a.value||a.status)+'</strong>'+(a.trajectory&&a.trajectory!=='unknown'?' · '+esc(a.trajectory):'')+'<div class="hint">'+esc(a.definition||'')+'</div></div>').join('');const unresolved=(fp.unresolved_or_mixed_axes||[]).length;document.getElementById('fingerprint').innerHTML=(rows||'<p>No axes met the frozen evidence/confidence threshold.</p>')+(unresolved?'<p class="hint">'+unresolved+' additional axes remain mixed, context-dependent, or insufficiently observed.</p>':'')}
async function revealStudy(){const b=document.getElementById('revealButton');b.disabled=true;b.textContent='Revealing frozen prediction…';const r=await fetch('/api/study/sessions/'+sessionId+'/reveal',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});const d=await r.json();if(!r.ok){b.disabled=false;b.textContent='Reveal the blinded Astro/HD prediction';return alert(d.detail||'Reveal failed')}const target=document.getElementById('predictionReveal');target.classList.remove('hidden');target.innerHTML=renderPrediction(d.prediction_reveal);b.classList.add('hidden')}
function renderPrediction(p){let html='<h2>What was frozen before your answers</h2>';for(const layer of (p.layers||[])){html+='<div class="card"><h3>'+esc(layer.layer_id.replaceAll('_',' '))+'</h3><p>'+esc(layer.explanation||layer.outcome_comparison_status)+'</p>';if(layer.layer_id==='human_design_connection_v1'&&layer.preanswer_payload&&layer.preanswer_payload.connection){const c=layer.preanswer_payload.connection;html+='<p><strong>Connection mechanics:</strong> '+esc(c.center_configuration||'')+' · '+esc(c.composite_definition||'')+'</p>';if(c.channels)html+='<p class="hint">Channels: '+esc(c.channels.map(x=>x.channel+' ('+x.kind+')').join(', '))+'</p>'}if(layer.layer_id==='astro_rrf_directional_v0_4'&&layer.preanswer_payload&&layer.preanswer_payload.v0_1_raw_scoring){html+='<p><strong>Frozen directional raw signals:</strong></p><ul>'+layer.preanswer_payload.v0_1_raw_scoring.directional_scores.map(x=>'<li>'+esc(x.actor.toUpperCase()+' · '+x.axis.replaceAll('_',' ')+' = '+x.score)+'</li>').join('')+'</ul>'}html+='</div>'}if(!p.formal_hit_miss_summary)html+='<div class="notice"><strong>Why there is not a hit/miss percentage yet:</strong> the raw relationship signals were frozen before your answers, but the ordinal calibration needed to call those scores high/low is not yet frozen. The study will not invent that threshold after seeing your relationship.</div>';return html}"""
